        // --- Magnifier Logic ---
        const lens = document.getElementById('lens');
        const lensContent = document.getElementById('lens-content');
        const mainContent = document.body; // We clone the whole body or specific area
        const zoomLevel = 1.8; // Slightly magnified

        // Initial setup for lens content
        // To make it performant and simple, we will clone the visible area logic conceptually
        // But for a static demo effect, we can just use a CSS approach or simplified JS cloning.
        // Let's implement a real-time clone of the 'main' area for the lens.

        let isHovering = false;

        document.addEventListener('mousemove', (e) => {
            // Position lens
            lens.style.left = (e.clientX - 70) + 'px'; // Center it
            lens.style.top = (e.clientY - 70) + 'px';

            if (!isHovering) return;

            // Update content position inside lens
            // The math: Move the cloned content in the opposite direction * zoom
            const offsetX = (e.clientX * (zoomLevel - 1));
            const offsetY = (e.clientY * (zoomLevel - 1));

            lensContent.style.transform = `scale(${zoomLevel}) translate(${-e.clientX / zoomLevel}px, ${-e.clientY / zoomLevel}px)`;
        });

        // Enable magnifier on interaction
        document.addEventListener('mouseenter', () => {
            // Clone body content into lens once to avoid heavy re-rendering every frame if possible
            // For this demo, we'll update the clone periodically or on entry.
            // A simpler trick for "static-ish" UI: Just clone once on load, update position.

            // Actually, let's do a lightweight version:
            // Clone the main scroll area
            const source = document.getElementById('main-scroll');
            const clone = source.cloneNode(true);
            clone.style.width = source.scrollWidth + 'px';
            clone.style.height = source.scrollHeight + 'px';
            clone.style.pointerEvents = 'none';

            lensContent.innerHTML = '';
            lensContent.appendChild(clone);

            // Reset styles for the clone inside lens
            clone.style.position = 'absolute';
            clone.style.top = '0';
            clone.style.left = '0';

            isHovering = true;
            lens.style.opacity = '1';
        }, true); // Capture phase

        document.addEventListener('mouseleave', () => {
            isHovering = false;
            lens.style.opacity = '0';
        }, true);

